/* k15_cutoff: for each point, count neighbours within radius r, scanning
 * points sorted by x and stopping once x is out of range.
 * IRREGULAR: points are clustered, so points inside dense clusters scan
 * far more neighbours than isolated ones (like molecular dynamics). */
#include <math.h>
#include <omp.h>
#include "common.h"

/* === KERNEL BEGIN === */
static void kernel(long n, double r, const double *x, const double *y, int *nb) {
    const double r2 = r * r;

    /* 
     * The workload is highly irregular because points are clustered.
     * A point in a dense cluster will scan many more neighbours than a point 
     * in a sparse region. 'schedule(guided)' is used to load balance effectively
     * while maintaining low overhead by starting with larger chunks and 
     * reducing them as the computation progresses.
     */
    #pragma omp parallel for schedule(guided)
    for (long i = 0; i < n; i++) {
        int c = 0;
        const double xi = x[i];
        const double yi = y[i];

        /* 
         * Forward scan: Scan points with index j > i.
         * Since x is sorted, we can stop as soon as x[j] - xi > r.
         */
        for (long j = i + 1; j < n; j++) {
            const double dx = x[j] - xi;
            if (dx > r) break;
            const double dy = y[j] - yi;
            if (dx * dx + dy * dy <= r2) {
                c++;
            }
        }

        /* 
         * Backward scan: Scan points with index j < i.
         * Similarly, we stop as soon as xi - x[j] > r.
         */
        for (long j = i - 1; j >= 0; j--) {
            const double dx = xi - x[j];
            if (dx > r) break;
            const double dy = yi - y[j];
            if (dx * dx + dy * dy <= r2) {
                c++;
            }
        }
        nb[i] = c;
    }
}
/* === KERNEL END === */

static int cmp_x(const void *a, const void *b) {
    double d = ((const double *)a)[0] - ((const double *)b)[0];
    return (d > 0) - (d < 0);
}

int main(int argc, char **argv) {
    long n = arg_long(argc, argv, 1, 400000);
